-- Payroll (stage 2, docs/design/22-payroll.md §5.1).
-- Generated by `prisma migrate dev --create-only`, then extended by hand (Prisma leaves CHECK
-- constraints, functions and triggers alone when it diffs the schema): CHECK constraints on
-- employee and payroll_run, and payroll_run made append-only like journal_line (02 §1).

-- CreateEnum
CREATE TYPE "employee_kind" AS ENUM ('officer', 'employee');

-- CreateEnum
CREATE TYPE "withholding_column" AS ENUM ('kou', 'otsu');

-- CreateEnum
CREATE TYPE "premium_timing" AS ENUM ('next_month', 'same_month');

-- AlterEnum
ALTER TYPE "source_kind" ADD VALUE 'payroll';

-- CreateTable
CREATE TABLE "employee" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "kind" "employee_kind" NOT NULL,
    "birth_date" DATE NOT NULL,
    "base_pay" BIGINT NOT NULL,
    "commute_allowance" BIGINT NOT NULL DEFAULT 0,
    "social_insured" BOOLEAN NOT NULL,
    "insured_from" DATE,
    "health_smr" BIGINT,
    "pension_smr" BIGINT,
    "employment_insured" BOOLEAN NOT NULL,
    "tax_column" "withholding_column" NOT NULL,
    "dependents" INTEGER NOT NULL DEFAULT 0,
    "resident_tax" BIGINT NOT NULL DEFAULT 0,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,

    CONSTRAINT "employee_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "payroll_run" (
    "id" TEXT NOT NULL,
    "pay_month" TEXT NOT NULL,
    "payment_date" DATE NOT NULL,
    "premium_timing" "premium_timing" NOT NULL,
    "premium_month" TEXT NOT NULL,
    "pay_from_wallet_id" TEXT,
    "withholding_special_due" BOOLEAN NOT NULL,
    "resident_tax_special_due" BOOLEAN NOT NULL,
    "table_ids" JSONB NOT NULL,
    "items" JSONB NOT NULL,
    "pay_entry_id" TEXT NOT NULL,
    "employer_entry_id" TEXT,
    "confirmed_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "confirmed_by" TEXT NOT NULL,

    CONSTRAINT "payroll_run_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "payroll_run_pay_month_key" ON "payroll_run"("pay_month");

-- CreateIndex
CREATE UNIQUE INDEX "payroll_run_premium_month_key" ON "payroll_run"("premium_month");

-- ---------------------------------------------------------------------------
-- CHECK constraints
-- ---------------------------------------------------------------------------

ALTER TABLE "employee"
  ADD CONSTRAINT "employee_dependents_nonnegative" CHECK ("dependents" >= 0),
  ADD CONSTRAINT "employee_amounts_nonnegative"
    CHECK ("base_pay" >= 0 AND "commute_allowance" >= 0 AND "resident_tax" >= 0),
  ADD CONSTRAINT "employee_smr_positive"
    CHECK (("health_smr" IS NULL OR "health_smr" > 0) AND ("pension_smr" IS NULL OR "pension_smr" > 0)),
  ADD CONSTRAINT "employee_social_insured_fields" CHECK (
    NOT "social_insured"
    OR ("insured_from" IS NOT NULL AND "health_smr" IS NOT NULL AND "pension_smr" IS NOT NULL)
  ),
  ADD CONSTRAINT "employee_officer_not_employment_insured"
    CHECK ("kind" <> 'officer' OR NOT "employment_insured");

ALTER TABLE "payroll_run"
  ADD CONSTRAINT "payroll_run_pay_month_format" CHECK ("pay_month" ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  ADD CONSTRAINT "payroll_run_premium_month_format"
    CHECK ("premium_month" ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  -- 支給月 is the month of the payment date.
  ADD CONSTRAINT "payroll_run_pay_month_of_payment_date" CHECK (
    "pay_month" = lpad(extract(year FROM "payment_date")::int::text, 4, '0') || '-'
                  || lpad(extract(month FROM "payment_date")::int::text, 2, '0')
  ),
  -- 翌月控除: the month before the pay month; 当月控除: the pay month.
  ADD CONSTRAINT "payroll_run_premium_month_of_timing" CHECK (
    ("premium_timing" = 'same_month' AND "premium_month" = "pay_month")
    OR ("premium_timing" = 'next_month' AND "premium_month" =
          lpad(((substr("pay_month", 1, 4)::int * 12 + substr("pay_month", 6, 2)::int - 2) / 12)::text, 4, '0')
          || '-'
          || lpad(((substr("pay_month", 1, 4)::int * 12 + substr("pay_month", 6, 2)::int - 2) % 12 + 1)::text, 2, '0'))
  );

-- ---------------------------------------------------------------------------
-- payroll_run: append-only (UPDATE / DELETE / TRUNCATE rejected)
-- ---------------------------------------------------------------------------

CREATE FUNCTION "ledger_payroll_run_reject_change"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'ledger guard: payroll_run is append-only (% of % rejected)', TG_OP, OLD."id";
END;
$$;

CREATE TRIGGER "payroll_run_reject_change"
  BEFORE UPDATE OR DELETE ON "payroll_run"
  FOR EACH ROW EXECUTE FUNCTION "ledger_payroll_run_reject_change"();

CREATE TRIGGER "payroll_run_reject_truncate"
  BEFORE TRUNCATE ON "payroll_run"
  FOR EACH STATEMENT EXECUTE FUNCTION "ledger_reject_truncate"();
